package com.palettejourney;

import android.app.Activity;
import android.app.AlertDialog;
import android.os.Bundle;
import android.os.Handler;
import android.car.Car;
import android.car.VehiclePropertyIds;
import android.car.hardware.property.CarPropertyManager;
import android.webkit.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Console speed/gear drive a fast, explicitly virtual route. Never writes vehicle GPS or normal family rewards. */
public class DevDriveActivity extends VehicleActivity {
    private final Handler main=new Handler();private final ExecutorService network=Executors.newSingleThreadExecutor(),signals=Executors.newSingleThreadExecutor();
    private volatile boolean active;private volatile int generation;private volatile Float speed;private volatile Integer gear;private Car car;private CarPropertyManager properties;
    private TextView metrics,stage,distance,parking,coordinates;private ProgressBar routeProgress,parkProgress;private WebView preview;
    private Button pause,reset,newFamily,connect;private GridLayout destinations;private final List<Button> cities=new ArrayList<>();
    private String participant,tripId,selected,highlighted,previewRegion,signature;private JSONObject latestCatalog;private boolean busy,commandBusy,loaded,running;private int routeMeters=300,parkMillis=5000;
    interface Work{JSONObject run()throws Exception;}
    private boolean allowed(){return BuildConfig.EMULATOR_DEMO&&("ranchu".equals(android.os.Build.HARDWARE)||"goldfish".equals(android.os.Build.HARDWARE));}
    private Button button(LinearLayout parent,String name,Runnable action){Button b=new Button(this);b.setText(name);DevUi.button(b);parent.addView(b,new LinearLayout.LayoutParams(-1,-2));b.setOnClickListener(v->action.run());return b;}
    @Override public void onCreate(Bundle state){super.onCreate(state);
        LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(DevUi.dp(this,20),DevUi.dp(this,12),DevUi.dp(this,20),DevUi.dp(this,12));root.setBackgroundColor(DevUi.BG);
        LinearLayout header=new LinearLayout(this);header.addView(DevUi.text(this,"개발자 주행 시연",30),new LinearLayout.LayoutParams(0,-2,1));root.addView(header);root.addView(DevUi.text(this,"콘솔 → 모의 이동 · 실제 GPS와 별도",20));
        LinearLayout body=new LinearLayout(this);root.addView(body,new LinearLayout.LayoutParams(-1,0,1));ScrollView scroll=new ScrollView(this);LinearLayout left=new LinearLayout(this);left.setOrientation(1);left.setPadding(0,0,DevUi.dp(this,16),0);scroll.addView(left);body.addView(scroll,new LinearLayout.LayoutParams(0,-1,0.42f));
        metrics=DevUi.text(this,"속도 — · 기어 —",30);metrics.setTag("drive-metrics");left.addView(metrics);left.addView(DevUi.text(this,"도착지 선택",24));destinations=new GridLayout(this);destinations.setColumnCount(3);left.addView(destinations);
        stage=DevUi.text(this,"가족 연결 확인 중",24);stage.setTag("drive-stage");left.addView(stage);distance=DevUi.text(this,"주행 0 / 300m",22);distance.setTag("drive-distance");left.addView(distance);routeProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);routeProgress.setMax(300);left.addView(routeProgress,new LinearLayout.LayoutParams(-1,DevUi.dp(this,18)));
        parking=DevUi.text(this,"도착 후 P·정지 5초",22);left.addView(parking);parkProgress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);parkProgress.setMax(5000);left.addView(parkProgress,new LinearLayout.LayoutParams(-1,DevUi.dp(this,18)));coordinates=DevUi.text(this,"모의 좌표 대기",18);left.addView(coordinates);
        pause=button(left,"시연 시작",()->{if(tripId==null){if(selected!=null)choose(selected);return;}running=!running;buttons();});pause.setTag("drive-pause");
        reset=button(left,"지역 방문 초기화",()->new AlertDialog.Builder(this).setTitle("지역 방문 초기화").setMessage("이 시연 가족의 지역 보상을 다시 잠급니다. 가족 연결과 그림·대화는 유지됩니다.").setNegativeButton("취소",null).setPositiveButton("초기화",(d,w)->{running=false;dispatch(()->VehicleApi.request("/api/session/visits/reset","POST",new JSONObject(),participant),true);}).show());
        connect=button(left,"휴대폰 연결",()->startActivity(new android.content.Intent(this,VehicleConnectionActivity.class)));
        newFamily=button(left,"새 시연 가족",()->{running=false;dispatch(()->{String owner=VehicleApi.randomToken();VehicleApi.request("/api/account/demo","PUT",new JSONObject(),owner);JSONObject session=VehicleApi.request("/api/sessions","POST",new JSONObject(),owner);String token=VehicleApi.randomToken();VehicleApi.request("/api/sessions/join","POST",new JSONObject().put("code",session.getString("code")),token);if(!active){VehicleApi.request("/api/sessions/"+session.getString("id"),"DELETE",null,owner);throw new java.io.IOException("CANCELLED");}VehicleApi.saveDemo(this,token);participant=token;return VehicleApi.request("/api/session/visits/drive","GET",null,token);},true);});
        preview=new WebView(this);preview.setTag("drive-preview");preview.setBackgroundColor(DevUi.BG);preview.getSettings().setJavaScriptEnabled(true);preview.getSettings().setAllowFileAccess(false);preview.getSettings().setAllowContentAccess(false);preview.getSettings().setBlockNetworkLoads(true);preview.getSettings().setDomStorageEnabled(false);preview.getSettings().setCacheMode(WebSettings.LOAD_NO_CACHE);preview.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView v,WebResourceRequest r){return true;}@Override public void onPageFinished(WebView v,String url){if(active&&latestCatalog!=null)v.evaluateJavascript("window.collection?.update("+CollectionRenderer.decode(CollectionRenderer.encoded(latestCatalog))+")",null);}});body.addView(preview,new LinearLayout.LayoutParams(0,-1,0.58f));setContentView(root);buttons();
    }
    private void buttons(){boolean ready=active&&allowed()&&!commandBusy;for(Button b:cities)b.setEnabled(ready&&loaded);pause.setEnabled(ready&&loaded&&tripId!=null);pause.setText(running?"시연 일시정지":"시연 이어가기");reset.setEnabled(ready&&loaded);newFamily.setEnabled(ready);connect.setEnabled(ready);}
    private void metrics(){String g=gear==null?"—":gear==4?"P":gear==8?"D":gear==2?"R":gear==1?"N":"?";metrics.setText((speed==null?"—":String.format(java.util.Locale.ROOT,"%.1f",Math.abs(speed)*3.6f))+" km/h · "+g);}
    private void choose(String id){if(!loaded||commandBusy)return;running=true;dispatch(()->VehicleApi.request("/api/session/visits/drive","POST",new JSONObject().put("action","select").put("regionId",id),participant),true);}
    private void dispatch(Work work,boolean replace){if(busy&&(!replace||commandBusy))return;busy=true;if(replace){commandBusy=true;generation++;}int expected=generation;buttons();network.execute(()->{try{JSONObject result=work.run();JSONObject catalog=result.getJSONObject("catalog");String region=result.isNull("regionId")?null:result.getString("regionId");String html=null;
        if(signature==null||!Objects.equals(region,previewRegion)){JSONObject scope=new JSONObject();if(region!=null){JSONArray list=catalog.getJSONArray("cities");for(int i=0;i<list.length();i++)if(region.equals(list.getJSONObject(i).getString("id")))scope.put("groupId",list.getJSONObject(i).getString("groupId")).put("cityId",region);}html=CollectionRenderer.html(this,catalog,scope).replace("</style>",".collection-trail,.collection-filter,.collection-note,.collection-card details{display:none!important}.vehicle-collection{padding:12px}.vehicle-collection .collection-card img{height:120px}.vehicle-collection .collection-card h4{font-size:20px}.vehicle-collection .collection-grid{gap:10px}.vehicle-collection .collection h2{font-size:26px}.collection-section-title{margin-top:12px}</style>");}
        String document=html;main.post(()->{if(!active||generation!=expected)return;try{apply(result,document);}catch(Exception e){stage.setText("표시 실패 · 다시 선택해주세요.");}busy=false;commandBusy=false;buttons();});
      }catch(Exception e){main.post(()->{if(!active||generation!=expected)return;busy=false;commandBusy=false;running=false;String message=e.getMessage();if("HTTP 401".equals(message)||"HTTP 403".equals(message)){loaded=false;tripId=null;latestCatalog=null;signature=null;preview.loadData("","text/html","UTF-8");stage.setText("새 시연 가족을 만들거나 가족 연결을 확인해주세요.");}else if("HTTP 409".equals(message)){tripId=null;stage.setText("방문 상태가 초기화됐어요 · 도시를 다시 선택해주세요.");}else stage.setText("서버 연결 실패 · 다시 선택해주세요.");buttons();});}});}
    private void apply(JSONObject result,String html)throws Exception{
        loaded=true;JSONObject catalog=result.getJSONObject("catalog");latestCatalog=catalog;selected=result.isNull("regionId")?null:result.getString("regionId");tripId=result.isNull("tripId")?null:result.getString("tripId");JSONObject policy=result.getJSONObject("policy");routeMeters=policy.getInt("routeMeters");parkMillis=policy.getInt("parkMs");
        if(cities.isEmpty()){JSONArray values=catalog.getJSONArray("cities");for(int i=0;i<values.length();i++){JSONObject city=values.getJSONObject(i);String id=city.getString("id");Button b=new Button(this);b.setText(city.getString("name"));b.setTag("drive-city-"+id);DevUi.button(b);GridLayout.LayoutParams p=new GridLayout.LayoutParams();p.width=0;p.height=-2;p.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);p.setMargins(DevUi.dp(this,3),DevUi.dp(this,3),DevUi.dp(this,3),DevUi.dp(this,3));destinations.addView(b,p);cities.add(b);b.setOnClickListener(v->choose(id));}}
        if(!Objects.equals(highlighted,selected)){for(Button b:cities)b.setActivated(b.getTag().equals("drive-city-"+selected));highlighted=selected;}
        int meters=(int)Math.floor(result.getDouble("distanceMeters")),park=result.getInt("parkMs");routeProgress.setMax(routeMeters);routeProgress.setProgress(meters);parkProgress.setMax(parkMillis);parkProgress.setProgress(park);distance.setText("모의 주행 "+meters+" / "+routeMeters+"m");parking.setText(result.getBoolean("arrived")?"P·정지 "+park/1000+" / "+parkMillis/1000+"초":"도착 후 P·정지 "+parkMillis/1000+"초");
        if(selected!=null)coordinates.setText(String.format(java.util.Locale.ROOT,"모의 위도 %.5f · 경도 %.5f",result.getDouble("latitude"),result.getDouble("longitude")));else coordinates.setText("모의 좌표 대기");
        if(result.getBoolean("collected")){running=false;stage.setText(result.optString("regionName")+" 수집 완료 · 색3개/스티커2개");}else if(selected==null){running=false;stage.setText(result.optBoolean("reset")?"초기화 완료 · 도시를 다시 선택해주세요.":"도시를 선택하고 콘솔에서 출발하세요.");}else if(!running)stage.setText("시연 일시정지");else if(speed==null||gear==null)stage.setText("콘솔 속도·기어 수신 대기");else stage.setText(result.getBoolean("arrived")?"도착 · P로 정차해주세요.":result.optString("regionName")+" 이동 중 · D로 주행해주세요.");
        if(html!=null)preview.loadDataWithBaseURL("https://drive.palette.invalid/",html,"text/html","UTF-8",null);else if(!catalog.toString().equals(signature))preview.evaluateJavascript("window.collection?.update("+CollectionRenderer.decode(CollectionRenderer.encoded(catalog))+")",null);signature=catalog.toString();previewRegion=selected;
    }
    private final CarPropertyManager.CarPropertyEventCallback listener=new CarPropertyManager.CarPropertyEventCallback(){public void onChangeEvent(android.car.hardware.CarPropertyValue value){if(!active)return;if(value.getPropertyId()==VehiclePropertyIds.PERF_VEHICLE_SPEED)speed=value.getStatus()==0?(Float)value.getValue():null;if(value.getPropertyId()==VehiclePropertyIds.GEAR_SELECTION)gear=value.getStatus()==0?(Integer)value.getValue():null;}public void onErrorEvent(int id,int area){if(id==VehiclePropertyIds.PERF_VEHICLE_SPEED)speed=null;if(id==VehiclePropertyIds.GEAR_SELECTION)gear=null;}};
    private void signals(){signals.execute(()->{try{car=Car.createCar(this);properties=(CarPropertyManager)car.getCarManager(Car.PROPERTY_SERVICE);if(!properties.registerCallback(listener,VehiclePropertyIds.PERF_VEHICLE_SPEED,CarPropertyManager.SENSOR_RATE_ONCHANGE)||!properties.registerCallback(listener,VehiclePropertyIds.GEAR_SELECTION,CarPropertyManager.SENSOR_RATE_ONCHANGE))throw new Exception();}catch(Exception e){speed=null;gear=null;}});}
    private final Runnable tick=new Runnable(){public void run(){if(!active)return;metrics();if(loaded&&!busy&&participant!=null){String trip=tripId;Float velocity=speed;Integer selectedGear=gear;boolean valid=running&&velocity!=null&&selectedGear!=null&&Float.isFinite(velocity)&&velocity>=0;dispatch(()->{if(trip==null)return VehicleApi.request("/api/session/visits/drive","GET",null,participant);JSONObject body=new JSONObject().put("action","tick").put("source","console-drive").put("tripId",trip).put("valid",valid).put("measuredAt",System.currentTimeMillis());if(valid)body.put("speedMps",velocity).put("gear",selectedGear);return VehicleApi.request("/api/session/visits/drive","POST",body,participant);},false);}main.postDelayed(this,1000);}};
    @Override protected void onStart(){super.onStart();active=true;generation++;busy=false;commandBusy=false;running=false;if(!allowed()){stage.setText("개발용 에뮬레이터 전용입니다.");buttons();return;}if(checkSelfPermission("android.car.permission.CAR_SPEED")!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{"android.car.permission.CAR_SPEED"},908);else signals();dispatch(()->{participant=VehicleApi.load(this);if(participant==null)throw new java.io.IOException("HTTP 401");return VehicleApi.request("/api/session/visits/drive","GET",null,participant);},false);main.post(tick);}
    @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] grants){super.onRequestPermissionsResult(code,permissions,grants);if(code==908&&active&&grants.length>0&&grants[0]==android.content.pm.PackageManager.PERMISSION_GRANTED)signals();}
    @Override protected void onStop(){active=false;generation++;running=false;main.removeCallbacks(tick);String token=participant,trip=tripId;if(token!=null&&trip!=null)network.execute(()->{try{VehicleApi.request("/api/session/visits/drive","POST",new JSONObject().put("action","tick").put("source","console-drive").put("tripId",trip).put("valid",false),token);}catch(Exception ignored){}});signals.execute(()->{if(properties!=null){properties.unregisterCallback(listener);properties=null;}if(car!=null){try{car.disconnect();}catch(IllegalArgumentException ignored){}finally{car=null;}}speed=null;gear=null;});preview.loadData("","text/html","UTF-8");signature=null;latestCatalog=null;super.onStop();}
    @Override protected void onDestroy(){preview.destroy();network.shutdown();signals.shutdown();super.onDestroy();}
}
